	if len(hashLit.Pairs) != 2 {
		t.Errorf("hashLit has wrong number of pairs. got=%d", len(hashLit.Pairs))
	}
}

func TestIndexExpression(t *testing.T) {
	input := `arr[0]`

	l := lexer.New(input)
	p := New(l)

	program := p.ParseProgram()
	checkParseErrors(t, p)

	if len(program.Statements) != 1 {
