				i+1, elementType.String(), elemType.String())
		}
	}

	return NewArrayType(elementType)
}

// checkHashLiteral checks a hash literal
func (c *Checker) checkHashLiteral(expr *ast.HashLiteral) Type {
	if len(expr.Pairs) == 0 {
