// compileForStatement compiles a for statement
func (c *Compiler) compileForStatement(stmt *ast.ForStatement) {
	// Enter new scope for loop
	c.scopeLevel++
	loopLocals := make(map[string]int)

	// Define loop variable if present
	if stmt.LoopVar != nil {
