	for _, s := range stmt.Statements {
		c.compileStatement(s)
	}
}

// compileExpression compiles an expression
func (c *Compiler) compileExpression(expr ast.Expression) {
	switch e := expr.(type) {
	case *ast.IntegerLiteral:
		c.compileIntegerLiteral(e)
